/**
 * magnet-templates.js — starter-flow gallery for "New magnet from a template".
 *
 * Pure client-side: a template is just the SAME bare-key shape
 * collectAppearance()/applyAppearance() already use (magnets-route.js /
 * magnets.js), plus a `steps` array in the SDK's real mag_macro_steps shape
 * (step_type/step_columns/step_prompts/step_options/step_description — see
 * starterFlow() in service-api's magnets.js). No new backend surface: a
 * template is applied by PATCHing a freshly-provisioned DRAFT magnet with
 * this data, the exact same PATCH /:guid the Save button already sends —
 * see provisionAndOpen()'s optional `template` param in magnets-route.js.
 *
 * step_columns values are restricted to packages/shared's LEAD_CAPTURE_FIELDS
 * (the only columns the capture endpoint actually reads an answer into) —
 * not guessed field names.
 *
 * `category`/`tags`/`featured` are browse-page metadata only: the /templates
 * gallery filters and badges on them. They are never sent to the API (see
 * applyTemplate(), which only reads name/appearance/steps), so adding one to a
 * template can never change the magnet it produces.
 */

import { HANDOFF, setHandoff, takeHandoff, peekHandoff } from '../core/routeHandoff.js';

const ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ESC[c]);

