// Which lead fields a template actually captures, in first-asked order. Derived from
// the steps rather than stored alongside them, so it cannot drift out of sync when a
// template's flow is edited.
export function templateFields(t) {
  const seen = [];
  for (const s of (t.steps || [])) {
    for (const c of (s.step_columns || [])) if (c && !seen.includes(c)) seen.push(c);
  }
  return seen;
}

// ── derived card-face art ────────────────────────────────────────────────────
// The browse page needs a picture of the flow, and a hand-drawn thumbnail per
// template is exactly the drift shape this file already avoids for templateFields():
// edit a template's first question and a stored thumbnail silently lies. So the art is
// GENERATED from steps[0] — the first thing a visitor actually sees — and can never
// describe a flow the template no longer has.

// The faux input shows the answer AFFORDANCE, not the question (the bubble above it
// already carries the question). Keyed by step_type, the same way the SDK picks an
// input's own placeholder.
const INPUT_PLACEHOLDER = {
  text: 'Type your answer',
  email: 'you@example.com',
  phone: '(555) 123-4567',
};

export function derivedPreviewHTML(t) {
  const first = (t.steps || [])[0] || {};
  const line = (first.step_prompts || [])[0] || '';
  let body = '';
  if (first.step_type === 'single_select' || first.step_type === 'multi_select') {
    body = (first.step_options || []).slice(0, 3)
      .map((o) => `<span class="mag-tpl-pv__btn">${esc(o?.label)}</span>`).join('');
  } else if (INPUT_PLACEHOLDER[first.step_type]) {
    body = `<span class="mag-tpl-pv__input">${esc(INPUT_PLACEHOLDER[first.step_type])}</span>`;
  } else if (first.step_type === 'scheduler') {
    body = `<span class="mag-tpl-pv__cal"><span class="material-symbols-outlined" aria-hidden="true">calendar_month</span>Pick a time</span>`;
  }
  // aria-hidden: decorative art. The card's real name/description/buttons carry
  // everything a screen reader needs, so this would only be duplicate noise.
  return `<div class="mag-tpl-card__preview" aria-hidden="true"><span class="mag-tpl-pv__bubble">${esc(line)}</span>${body}</div>`;
}

/**
 * One template card. Shared by the picker modal and the /templates browse page so the
 * two cannot drift — the same reason stepTypes.js and magnetAppearance.js exist.
 * `detail` adds the step count + captured-field line, which the browse page has room
 * for and the modal does not.
 *
 * `gallery` is the browse page's richer face: derived art, tag chips, the featured
 * badge and a secondary Preview button. `canUse` drops the Use button for a persona
 * without provisioning rights (Preview stays — looking is always allowed).
 *
 * Every gallery-only extra is interpolated INLINE, never onto a line of its own, so a
 * plain templateCardHTML(t) still emits byte-for-byte the markup the picker modal has
 * always rendered. Same-elements is not enough here: the modal is the proven surface.
 */
export function templateCardHTML(t, { detail = false, gallery = false, canUse = true } = {}) {
  const fields = detail ? templateFields(t) : [];
  const galleryCls = gallery ? ' mag-tpl-card--gallery' : '';
  const catAttr = gallery ? ` data-cat="${esc(t.category || '')}"` : '';
  const badge = gallery && t.featured
    ? `<span class="m5t-badge m5t-badge--featured m5t-featured-corner">Most popular</span>`
    : '';
  const art = gallery ? derivedPreviewHTML(t) : '';
  const tags = gallery && (t.tags || []).length
    ? `<div class="m5t-chip-row mag-tpl-card__tags">${t.tags.map((tag) => `<span class="m5t-chip">${esc(tag)}</span>`).join('')}</div>`
    : '';
  const useBtn = canUse
    ? `<button class="mag-tpl-card__btn" type="button" data-tpl="${t.id}">
        <span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span>Use this template
      </button>`
    : '';
  const previewBtn = gallery
    ? `<button class="mag-tpl-card__btn mag-tpl-card__btn--ghost" type="button" data-preview="${t.id}">
        <span class="material-symbols-outlined" aria-hidden="true">visibility</span>Preview
      </button>`
    : '';
  return `
    <div class="mag-tpl-card${galleryCls}"${catAttr}>${badge}${art}
      <span class="mag-tpl-card__icon"><span class="material-symbols-outlined" aria-hidden="true">${t.icon}</span></span>
      <span class="mag-tpl-card__name">${t.name}</span>
      <p class="mag-tpl-card__desc">${t.description}</p>${tags}
      ${detail ? `<p class="mag-tpl-card__meta">
        <span><span class="material-symbols-outlined" aria-hidden="true">list_alt</span>${(t.steps || []).length} steps</span>
        ${fields.length ? `<span><span class="material-symbols-outlined" aria-hidden="true">badge</span>Captures ${fields.join(', ')}</span>` : ''}
      </p>` : ''}
      ${gallery ? `<div class="mag-tpl-card__actions">${useBtn}${previewBtn}</div>` : useBtn}
    </div>`;
}

// ── cross-route handoff ──────────────────────────────────────────────────────
// The /templates browse page cannot provision a magnet itself: that path (owner
// picker → provisionDraft → applyTemplate → open the edit modal) lives in
// magnets-route and depends on its loaded state. So the page parks the choice here
// and navigates to #/magnets, which claims it on init.
//
// The parking mechanism moved to core/routeHandoff.js once the dashboard's campaign
// drill-through became the second thing needing it — see that file for why this is
// module state and not a hash query param, and for the one-shot reasoning. These two
// wrappers stay so callers keep dealing in templates rather than raw handoff keys.
//
// TTL: one-shot alone is not enough here. #/magnets bounces to signin when the guard
// says so, and a click that never reached the destination leaves the choice parked for
// the rest of the session — so a visitor who picks a template, wanders the app for an
// hour, and finally opens Magnets gets a surprise draft they no longer remember asking
// for. Five minutes is "I clicked that just now" and nothing longer.
const PENDING_TEMPLATE_TTL_MS = 5 * 60 * 1000;

export function setPendingTemplate(id) {
  setHandoff(HANDOFF.MAGNET_TEMPLATE, { id, at: Date.now() });
}

/**
 * A parked value → its template, or null when it is stale, unknown, or absent.
 * A bare string is the pre-TTL shape: still honored, since a session can straddle a
 * deploy with the old parker and the new claimant.
 */
function resolveParked(parked) {
  if (!parked) return null;
  if (typeof parked === 'string') return MAGNET_TEMPLATES.find((x) => x.id === parked) || null;
  const { id, at } = parked;
  if (typeof at === 'number' && (Date.now() - at) >= PENDING_TEMPLATE_TTL_MS) return null;
  return MAGNET_TEMPLATES.find((x) => x.id === id) || null;
}

export function takePendingTemplate() {
  return resolveParked(takeHandoff(HANDOFF.MAGNET_TEMPLATE));
}

/** Same answer, without spending the one delivery takePendingTemplate() grants. */
export function peekPendingTemplate() {
  return resolveParked(peekHandoff(HANDOFF.MAGNET_TEMPLATE));
}

